import shutil, subprocess, os, sys
s='[C][C][C][C][Branch1][=Branch2][C][N][Branch1][Ring2][C][Ring1][Ring2][C][O]'
print('Input:', s)
for exe in ['obabel','xtb','mopac','psi4','g16','nwchem']:
    print(exe, shutil.which(exe))
try:
    from rdkit import Chem
    m=Chem.MolFromSmiles(s)
    print('RDKit parse:', m is not None)
    if m:
        print('Canonical SMILES:', Chem.MolToSmiles(m))
        print('Atoms:', m.GetNumAtoms(), 'Bonds:', m.GetNumBonds())
except Exception as e:
    print('RDKit error:', repr(e))
try:
    import pyscf
    print('PySCF:', pyscf.__version__)
except Exception as e:
    print('PySCF unavailable:', repr(e))
